-- kafaa_cleanup_fs31_award_notices (2/4) · data clean-up 2026-10-13: the 102 FS31 "Micro-credential awarded" notifications missing on live
-- Apply with apply_migration name "kafaa_cleanup_fs31_award_notices", in ORDER.txt order. Insert-only into kafaa_notifications.
-- Rows nt-mc-mca-<person>-<code>-<date>-awarded, generated by kafaa/scripts/seed/ext/fs31-future-credentials.mjs and copied verbatim
-- from kafaa/supabase/seed.sql (main); the seed file itself is not applied. Every referenced award (kafaa_microcred_awards
-- mca-<person>-<code>-<date>, status 'awarded') and person exists live (checked 2026-10-13: 102/102). kafaa.seeding = 'on' for this
-- transaction, as seed.sql does, so the kafaa_notifications_audit row trigger writes no audit rows for seed rows.
-- on conflict (id) do nothing; the guard rolls the part back unless exactly 102 rows were inserted and each matches its award's holder.
select set_config('kafaa.seeding', 'on', true);
on conflict (id) do nothing;
do $g$ declare n integer; m integer; begin
  select count(*)::int, count(*) filter (where exists (select 1 from kafaa_microcred_awards a join kafaa_people p on p.id = a.person_id
           where a.id = regexp_replace(regexp_replace(t.id, '^nt-mc-', ''), '-awarded$', '') and a.person_id = t.person_id and a.status = 'awarded'))::int
    into n, m
    from kafaa_notifications t where t.xmin::text = (txid_current() % 4294967296)::text and t.id like 'nt-mc-mca-%-awarded';
  if n is distinct from 102 or m is distinct from 102 then raise exception 'cleanup 02: inserted % rows, % matching their award (expected 102/102)', n, m; end if;
end $g$;
